definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '20'))
    timeout(time: 120, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  // Schedule disabled: NO automatic GC/dedupe until the stacks are
  // up (per operator). Manual/on-demand only. Re-add
  // cron('H 4 * * 0') once stacks are running.

  stages {
    stage('Dedupe /mnt/btrfs') {
      steps {
        sh '''
          set -e
          # Jenkins agents share the host docker.sock but not host
          # paths, so run duperemove in a privileged container that
          # bind-mounts the host btrfs subvol. --privileged is needed
          # for the FIDEDUPERANGE ioctl. Hashfile lives on the btrfs
          # itself (persistent + resumable, never tmpfs/RAM).
          docker run --rm --privileged -v /mnt/btrfs:/data alpine:3.20 sh -c '
            set -e
            apk add --no-cache duperemove btrfs-progs >/dev/null
            echo "== BEFORE =="; btrfs filesystem usage /data 2>/dev/null | grep -iE "Device size|Used:|Free .est" | head
            duperemove -dr --hashfile=/data/.duperemove.hash --dedupe-options=partial /data
            echo "== AFTER =="; btrfs filesystem usage /data 2>/dev/null | grep -iE "Device size|Used:|Free .est" | head
          '
        '''
      }
    }
  }

  post {
    always { cleanWs() }
  }
}
